// Synthetic NFS BUN files generated by the tests (no game data): a chunk builder and a texture pack (TPK) builder that follows the layout rules
// documented in docs/ASSET_FORMATS.md.
#pragma once
#include "asset_common.hpp"

namespace asstest {

struct Bun {
    std::vector<uint8_t> b;
    size_t begin(uint32_t id) { size_t h = b.size(); put32(b, id); put32(b, 0); return h; }
    void end(size_t h) { uint32_t n = uint32_t(b.size() - h - 8); for (int i = 0; i < 4; ++i) b[h + 4 + i] = uint8_t(n >> (8 * i)); }
    void chunk(uint32_t id, const std::vector<uint8_t>& payload) { size_t h = begin(id); b.insert(b.end(), payload.begin(), payload.end()); end(h); }
    // a padding chunk that makes the NEXT chunk header start on a multiple of `align`
    void pad(uint64_t align) {
        size_t pos = b.size();
        size_t s = size_t((align - (pos + 8) % align) % align);
        chunk(0, std::vector<uint8_t>(s, 0));
    }
};

struct TexSpec {
    const char* name;
    uint32_t hash;
    uint8_t ct;               // 0x22 DXT1, 0x24 DXT3, 0x20 BGRA8, 0x08 P8
    uint32_t w, h, mips;
    uint32_t seed;
};

inline uint64_t level_bytes(uint8_t ct, uint32_t w, uint32_t h) {
    if (ct == 0x22) return uint64_t(std::max(1u, w / 4)) * std::max(1u, h / 4) * 8;
    if (ct == 0x24 || ct == 0x26) return uint64_t(std::max(1u, w / 4)) * std::max(1u, h / 4) * 16;
    if (ct == 0x20) return uint64_t(w) * h * 4;
    return uint64_t(w) * h;
}
inline uint64_t chain_bytes(const TexSpec& t) {
    uint64_t n = 0;
    for (uint32_t l = 0; l < t.mips; ++l) n += level_bytes(t.ct, std::max(1u, t.w >> l), std::max(1u, t.h >> l));
    return n;
}

inline std::vector<uint8_t> noise(size_t n, uint32_t seed) {
    std::vector<uint8_t> v(n);
    for (auto& x : v) x = uint8_t(rng_next(seed));
    return v;
}

// pixel bytes and palette of a generated texture (what the builder stores), to compare against what the library reads back
struct TexData { std::vector<uint8_t> image, palette; };
inline TexData tex_data(const TexSpec& t) {
    TexData d;
    d.image = noise(size_t(chain_bytes(t)), t.seed);
    if (t.ct == 0x08) { d.palette = noise(1024, t.seed + 777); for (auto& x : d.image) x = uint8_t(x); }
    return d;
}

inline void put_name(std::vector<uint8_t>& v, size_t off, const char* s, size_t max) { for (size_t i = 0; s[i] && i < max; ++i) v[off + i] = uint8_t(s[i]); }

// Append a complete TPK group (0xB3300000) for the textures.
inline void add_tpk(Bun& bun, const char* pack_name, uint32_t pack_hash, const std::vector<TexSpec>& tex) {
    const size_t n = tex.size();
    std::vector<uint8_t> hdr(0x7C, 0);
    hdr[0] = 5;
    put_name(hdr, 4, pack_name, 27);
    put_name(hdr, 0x20, "Global\\Synthetic.tpk", 60);
    for (int i = 0; i < 4; ++i) hdr[0x60 + i] = uint8_t(pack_hash >> (8 * i));

    // layout: palette pool first, then images on 128 byte boundaries
    std::vector<TexData> data;
    for (auto& t : tex) data.push_back(tex_data(t));
    std::vector<uint32_t> pal_off(n), place(n);
    uint64_t pool = 0;
    for (size_t i = 0; i < n; ++i) { pal_off[i] = uint32_t(pool); pool += data[i].palette.size(); }
    uint64_t pos = (pool + 127) / 128 * 128;
    for (size_t i = 0; i < n; ++i) { place[i] = uint32_t(pos); pos = (pos + data[i].image.size() + 127) / 128 * 128; }
    uint64_t total = n ? uint64_t(place[n - 1]) + data[n - 1].image.size() : pool;

    std::vector<uint8_t> hashes, recs, fmts;
    for (size_t i = 0; i < n; ++i) {
        put32(hashes, tex[i].hash);
        put32(hashes, 0);
        std::vector<uint8_t> r(0x7C, 0);
        put_name(r, 0x0C, tex[i].name, 23);
        auto w32 = [&](size_t off, uint32_t v) { for (int k = 0; k < 4; ++k) r[off + k] = uint8_t(v >> (8 * k)); };
        w32(0x24, tex[i].hash);
        w32(0x28, 0x1A93CF);
        w32(0x30, place[i]);
        w32(0x34, pal_off[i]);
        w32(0x38, uint32_t(data[i].image.size()));
        w32(0x3C, uint32_t(data[i].palette.size()));
        w32(0x40, uint32_t(level_bytes(tex[i].ct, tex[i].w, tex[i].h)));
        r[0x44] = uint8_t(tex[i].w); r[0x45] = uint8_t(tex[i].w >> 8);
        r[0x46] = uint8_t(tex[i].h); r[0x47] = uint8_t(tex[i].h >> 8);
        uint32_t lw = 0, lh = 0;
        while ((1u << (lw + 1)) <= tex[i].w) ++lw;
        while ((1u << (lh + 1)) <= tex[i].h) ++lh;
        r[0x48] = uint8_t(lw); r[0x49] = uint8_t(lh); r[0x4A] = tex[i].ct;
        r[0x4E] = uint8_t(tex[i].mips);
        r[0x58] = 0; r[0x59] = 1;                       // some of the opaque fields the game keeps (0x100)
        r[0x63] = 1; r[0x65] = 1;
        recs.insert(recs.end(), r.begin(), r.end());
        uint32_t code = tex[i].ct == 0x22 ? 0x31545844u : tex[i].ct == 0x24 ? 0x33545844u : tex[i].ct == 0x20 ? 21u : 41u;
        put32(fmts, 0); put32(fmts, 0); put32(fmts, 1); put32(fmts, 5); put32(fmts, 6); put32(fmts, code); put32(fmts, 0); put32(fmts, 0);
    }

    size_t tpk = bun.begin(0xB3300000u);
    bun.pad(64);
    size_t info = bun.begin(0xB3310000u);
    bun.chunk(0x33310001u, hdr);
    bun.chunk(0x33310002u, hashes);
    bun.chunk(0x33310004u, recs);
    bun.chunk(0x33310005u, fmts);
    bun.end(info);
    bun.pad(128);
    size_t dgrp = bun.begin(0xB3320000u);
    std::vector<uint8_t> pre;
    put32(pre, 0); put32(pre, 0); put32(pre, 1); put32(pre, pack_hash); put32(pre, 0); put32(pre, 0);
    bun.chunk(0x33320001u, pre);
    bun.pad(128);
    size_t dc = bun.begin(0x33320002u);
    size_t base = (bun.b.size() + 127) / 128 * 128;
    bun.b.resize(base, 0x11);
    size_t base_pos = bun.b.size();
    bun.b.resize(base_pos + size_t(total), 0);
    for (size_t i = 0; i < n; ++i) {
        std::copy(data[i].palette.begin(), data[i].palette.end(), bun.b.begin() + base_pos + pal_off[i]);
        std::copy(data[i].image.begin(), data[i].image.end(), bun.b.begin() + base_pos + place[i]);
    }
    bun.end(dc);
    bun.end(dgrp);
    bun.end(tpk);
}

// A complete test file: some unrelated chunks, a padding chunk, a TPK, more unrelated chunks.
inline std::vector<uint8_t> make_bun(const std::vector<TexSpec>& tex, bool second_pack = false) {
    Bun bun;
    size_t sec = bun.begin(0x80134000u);
    bun.chunk(0, {});
    size_t sub = bun.begin(0x80134001u);
    bun.chunk(0x00134002u, noise(144, 1));
    bun.chunk(0x00134003u, noise(112, 2));
    bun.chunk(0x80134008u, {});
    bun.end(sub);
    bun.end(sec);
    bun.pad(128);
    add_tpk(bun, "SYNTHETIC", 0x5E8978A3u, tex);
    bun.chunk(0x00030201u, noise(4464, 3));
    bun.pad(128);
    bun.chunk(0x00030203u, noise(1048, 4));
    if (second_pack) {
        bun.pad(256);
        add_tpk(bun, "SECOND", 0x1234ABCDu, {{"ONLY_ONE", 0xABCDEF01u, 0x24, 8, 8, 2, 9}});
    }
    bun.chunk(0x0003B700u, noise(77, 5));          // odd size: the file is not aligned at the end
    return bun.b;
}

inline std::vector<TexSpec> default_textures() {
    return {
        {"TEX_DXT1_16", 0xAAAA0001u, 0x22, 16, 16, 3, 11},
        {"TEX_DXT3_32", 0xAAAA0002u, 0x24, 32, 16, 4, 12},
        {"TEX_BGRA_8", 0xAAAA0003u, 0x20, 8, 8, 1, 13},
        {"TEX_P8_16", 0xAAAA0004u, 0x08, 16, 16, 2, 14},
        {"TEX_P8_8", 0xAAAA0005u, 0x08, 8, 8, 1, 15},
        {"TEX_DXT1_64", 0xAAAA0006u, 0x22, 64, 64, 5, 16},
    };
}

}  // namespace asstest
